export const WORKFLOW_PUBLIC_SLUGS = PUBLIC_WORKFLOWS.map((w) => w.slug);

export function getPublicWorkflow(
  slug: string | null | undefined,
): PublicWorkflow | undefined {
  if (!slug) return undefined;
  return PUBLIC_WORKFLOWS.find((w) => w.slug === slug);
}
